package com.chatserver.auth

import io.ktor.server.application.*
import io.ktor.server.routing.*
import io.ktor.server.websocket.*
import io.ktor.websocket.*
import io.ktor.server.request.*
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

data class AuthenticatedSession(
    val userId: String,
    val signature: String,
    val timestamp: Long,
    val nonce: String
)

class NonceStore {
    private val usedNonces = ConcurrentHashMap<String, Long>()
    private val cleanupMutex = Mutex()
    private val NONCE_WINDOW_MS = 300_000L // 5 minutes

    suspend fun checkAndStore(nonce: String, timestamp: Long): Boolean {
        cleanupMutex.withLock {
            pruneExpired()
        }
        val compositeKey = buildNonceKey(nonce, timestamp)
        return usedNonces.putIfAbsent(compositeKey, timestamp) == null
    }

    private fun buildNonceKey(nonce: String, timestamp: Long): String {
        // Composite key binds nonce to its specific timestamp
        // Prevents reuse with different timestamps within the window
        return "$nonce|$timestamp"
    }

    private fun pruneExpired() {
        val cutoff = System.currentTimeMillis() - NONCE_WINDOW_MS
        usedNonces.entries.removeIf { it.value < cutoff }
    }

    fun windowContains(timestamp: Long): Boolean {
        val now = System.currentTimeMillis()
        return Math.abs(now - timestamp) <= NONCE_WINDOW_MS
    }
}

class SignatureVerifier(private val secretKey: String) {
    private val algorithm = "HmacSHA256"

    fun verify(userId: String, timestamp: Long, nonce: String, signature: String): Boolean {
        val payload = "$userId|$timestamp|$nonce"
        val expected = computeHmac(payload)
        return MessageDigest.isEqual(expected.toByteArray(), signature.toByteArray())
    }

    private fun computeHmac(data: String): String {
        val mac = Mac.getInstance(algorithm)
        val keySpec = SecretKeySpec(secretKey.toByteArray(), algorithm)
        mac.init(keySpec)
        return Base64.getEncoder().encodeToString(mac.doFinal(data.toByteArray()))
    }
}

class ChatAuthMiddleware(
    private val verifier: SignatureVerifier,
    private val nonceStore: NonceStore
) {
    suspend fun authenticate(call: ApplicationCall): AuthenticatedSession? {
        val userId = call.request.header("X-User-Id") ?: return null
        val signature = call.request.header("X-Signature") ?: return null
        val timestampStr = call.request.header("X-Timestamp") ?: return null
        val nonce = call.request.header("X-Nonce") ?: return null

        val timestamp = timestampStr.toLongOrNull() ?: return null

        // Step 1: Verify timestamp is within acceptable window
        if (!nonceStore.windowContains(timestamp)) {
            return null
        }

        // Step 2: Verify HMAC signature
        if (!verifier.verify(userId, timestamp, nonce, signature)) {
            return null
        }

        // Step 3: Check nonce hasn't been used
        // Note: nonce is checked AFTER signature verification for efficiency
        if (!nonceStore.checkAndStore(nonce, timestamp)) {
            return null
        }

        return AuthenticatedSession(userId, signature, timestamp, nonce)
    }
}

class ChatRoom {
    private val sessions = ConcurrentHashMap<String, WebSocketSession>()
    private val messageHistory = mutableListOf<Pair<String, String>>()

    suspend fun join(session: AuthenticatedSession, wsSession: WebSocketSession) {
        sessions[session.userId] = wsSession
        broadcast("System", "${session.userId} joined the chat")
    }

    suspend fun broadcast(sender: String, message: String) {
        messageHistory.add(sender to message)
        sessions.values.forEach { ws ->
            try {
                ws.send(Frame.Text("[$sender]: $message"))
            } catch (e: Exception) { /* session closed */ }
        }
    }

    fun leave(userId: String) {
        sessions.remove(userId)
    }
}

fun Application.configureChatRoutes() {
    val secret = environment.config.property("chat.hmac.secret").getString()
    val verifier = SignatureVerifier(secret)
    val nonceStore = NonceStore()
    val authMiddleware = ChatAuthMiddleware(verifier, nonceStore)
    val chatRoom = ChatRoom()

    install(WebSockets)

    routing {
        webSocket("/ws/chat") {
            val session = authMiddleware.authenticate(call)
            if (session == null) {
                close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Authentication failed"))
                return@webSocket
            }

            chatRoom.join(session, this)
            try {
                for (frame in incoming) {
                    if (frame is Frame.Text) {
                        chatRoom.broadcast(session.userId, frame.readText())
                    }
                }
            } finally {
                chatRoom.leave(session.userId)
            }
        }
    }
}
